import { describe, expect, it } from "vitest";
import { isSameMinute } from "../index.js";

describe("isSameMinute regressions", () => {
  it("returns true when only seconds and milliseconds differ", () => {
    const result = isSameMinute(
      new Date(2024, 0, 15, 10, 20, 1, 123),
      new Date(2024, 0, 15, 10, 20, 59, 999),
    );

    expect(result).toBe(true);
  });

  it("returns false when the local calendar minute differs", () => {
    const result = isSameMinute(
      new Date(2024, 0, 15, 10, 20, 59, 999),
      new Date(2024, 0, 15, 10, 21, 0, 0),
    );

    expect(result).toBe(false);
  });

  it("does not mutate the input dates", () => {
    const firstDate = new Date(2024, 0, 15, 10, 20, 1, 123);
    const secondDate = new Date(2024, 0, 15, 10, 20, 59, 999);
    const firstTime = firstDate.getTime();
    const secondTime = secondDate.getTime();

    expect(isSameMinute(firstDate, secondDate)).toBe(true);
    expect(firstDate.getTime()).toBe(firstTime);
    expect(secondDate.getTime()).toBe(secondTime);
  });
});

