import { describe, expect, it } from "vitest";
import { isSameMinute } from "../index.js";

describe("isSameMinute regression cases", () => {
  it("returns true for different seconds and milliseconds in the same local minute", () => {
    expect(
      isSameMinute(
        new Date(2024, 0, 15, 10, 20, 5, 123),
        new Date(2024, 0, 15, 10, 20, 59, 999),
      ),
    ).toBe(true);
  });

  it.each([
    [
      "different minutes",
      new Date(2024, 0, 15, 10, 20, 59, 999),
      new Date(2024, 0, 15, 10, 21),
    ],
    [
      "different hours",
      new Date(2024, 0, 15, 10, 20),
      new Date(2024, 0, 15, 11, 20),
    ],
    [
      "different days",
      new Date(2024, 0, 15, 10, 20),
      new Date(2024, 0, 16, 10, 20),
    ],
    [
      "different months",
      new Date(2024, 0, 15, 10, 20),
      new Date(2024, 1, 15, 10, 20),
    ],
    [
      "different years",
      new Date(2024, 0, 15, 10, 20),
      new Date(2025, 0, 15, 10, 20),
    ],
  ])("returns false for %s", (_description, laterDate, earlierDate) => {
    expect(isSameMinute(laterDate, earlierDate)).toBe(false);
  });
});

