+import { describe, expect, it } from "vitest";
+import { isSameMinute } from "../index.js";
+
+describe("isSameMinute regression tests", () => {
+  it("ignores seconds and milliseconds within the same minute", () => {
+    expect(
+      isSameMinute(
+        new Date(2024, 0, 15, 10, 20, 1, 1),
+        new Date(2024, 0, 15, 10, 20, 59, 999),
+      ),
+    ).toBe(true);
+  });
+
+  it("preserves distinctions between different calendar minutes", () => {
+    const date = new Date(2024, 0, 15, 10, 20);
+
+    expect(isSameMinute(date, new Date(2024, 0, 15, 10, 21))).toBe(false);
+    expect(isSameMinute(date, new Date(2024, 0, 15, 11, 20))).toBe(false);
+    expect(isSameMinute(date, new Date(2024, 0, 16, 10, 20))).toBe(false);
+    expect(isSameMinute(date, new Date(2024, 1, 15, 10, 20))).toBe(false);
+    expect(isSameMinute(date, new Date(2025, 0, 15, 10, 20))).toBe(false);
+  });
+
+  it("accepts string inputs and does not mutate Date inputs", () => {
+    const firstDate = new Date(2024, 0, 15, 10, 20, 5, 123);
+    const secondDate = new Date(2024, 0, 15, 10, 20, 55, 987);
+    const firstTime = firstDate.getTime();
+    const secondTime = secondDate.getTime();
+
+    expect(
+      isSameMinute(
+        "2024-01-15T10:20:05",
+        "2024-01-15T10:20:55.999",
+      ),
+    ).toBe(true);
