import { describe, expect, it } from "vitest";
import { isSameMinute } from "../index.js";

describe("isSameMinute regressions", () => {
  it("ignores seconds and milliseconds within the same local minute", () => {
    expect(
      isSameMinute(
        new Date(2024, 0, 15, 9, 42, 3, 1),
        new Date(2024, 0, 15, 9, 42, 58, 999),
      ),
    ).toBe(true);
  });

  it("preserves distinctions across minutes, hours, days, months, and years", () => {
    const date = new Date(2024, 0, 15, 9, 42);

    expect(isSameMinute(date, new Date(2024, 0, 15, 9, 43))).toBe(false);
    expect(isSameMinute(date, new Date(2024, 0, 15, 10, 42))).toBe(false);
    expect(isSameMinute(date, new Date(2024, 0, 16, 9, 42))).toBe(false);
    expect(isSameMinute(date, new Date(2024, 1, 15, 9, 42))).toBe(false);
    expect(isSameMinute(date, new Date(2025, 0, 15, 9, 42))).toBe(false);
  });

  it("does not mutate date inputs", () => {
    const laterDate = new Date(2024, 0, 15, 9, 42, 3, 1);
    const earlierDate = new Date(2024, 0, 15, 9, 42, 58, 999);
    const laterTime = laterDate.getTime();
    const earlierTime = earlierDate.getTime();

    expect(isSameMinute(laterDate, earlierDate)).toBe(true);
    expect(laterDate.getTime()).toBe(laterTime);
    expect(earlierDate.getTime()).toBe(earlierTime);
  });
});

