import { describe, expect, it } from "vitest";
import { isSameMinute } from "../index.js";

describe("isSameMinute regressions", () => {
  it("ignores seconds and milliseconds within the same local minute", () => {
    expect(
      isSameMinute(
        new Date(2014, 8 /* Sep */, 4, 6, 30, 15, 123),
        new Date(2014, 8 /* Sep */, 4, 6, 30, 59, 999),
      ),
    ).toBe(true);
  });

  it("distinguishes adjacent local minutes", () => {
    expect(
      isSameMinute(
        new Date(2014, 8 /* Sep */, 4, 6, 30, 59, 999),
        new Date(2014, 8 /* Sep */, 4, 6, 31),
      ),
    ).toBe(false);
  });

  it("preserves invalid date behavior", () => {
    expect(isSameMinute(new Date(NaN), new Date(NaN))).toBe(false);
  });
});

